            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == color:
                    # Start at the endpoint of the connected diagonal segment.
                    prev_r, prev_c = r - dr, c - dc
                    if not (0 <= prev_r < h and 0 <= prev_c < w and out[prev_r][prev_c] == color):
                        rays[(r, c, dr, dc, color)] = True
    for (r, c, dr, dc, color) in rays:
        # walk through existing cells of that ray, then continue to boundary
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] not in (color, grid[0][0]):
                break
            out[rr][cc] = color
            rr += dr
            cc += dc
    return out

