 "content": "def transform(grid):
    """Extend the marked diagonal rays through background to the grid edges."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # The ray colors are 1 by default; a 0 marker selects the non-background
    # colors directly touching it (as in the multicolor crossing example).
    ray_colors = {1}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg and grid[rr][cc] != 0:
                        ray_colors.add(grid[rr][cc])

    for color in ray_colors:
        for dr, dc in ((1, 1), (1, -1)):
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r - dr, c - dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue
                    run = []
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr, cc))
                        rr += dr
                        cc += dc
                    if len(run) < 2:
                        continue
                    for er, ec, sr, sc in (
                        (run[0][0], run[0][1], -dr, -dc),
                        (run[-1][0], run[-1][1], dr, dc),
                    ):
                        # A neighboring colored marker anchors that endpoint;
                        # otherwise extend until the board edge or an obstacle.
                        anchored = False
                        for ar, ac in ((er-1, ec), (er+1, ec), (er, ec-1), (er, ec+1)):
                            if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg and grid[ar][ac] != color:
                                anchored = True
                        if anchored:
                            continue
                        rr, cc = er + sr, ec + sc
                        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                            out[rr][cc] = color
                            rr += sr
                            cc += sc
    return out

if __name__ == '__main__':
    # Demo 1
    a = [[6] * 15 for _ in range(25)]
    a[15][0], a[15][1] = 9, 5
    a[16][0], a[16][1] = 5, 1
    a[17][2] = 1
    ao = transform(a)
    expected_a = [row[:] for row in a]
    for r in range(18, 25):
        expected_a[r][r - 15] = 1
    assert ao == expected_a

