        b[r][c] = v
    expected_b = [row[:] for row in b]
    for r in range(8):
        expected_b[r][r + 6] = 3
        expected_b[r][23 - r] = 4
    for r in range(11, 14):
        expected_b[r][23 - r] = 3
    assert transform(b) == expected_b

